function UIWithHistory(props: Omit<React.ComponentProps<typeof UI>, "uri" | "onNavigate" | "canGoBack" | "onGoBack" | "canGoForward" | "onGoForward" | "canGoUp" | "onGoUp"> & { initialUri?: string }) {
  const { initialUri = "/projects/my-project/designs/main", ...rest } = props;
  const { uri, canGoBack, canGoForward, canGoUp, goBack, goForward, goUp, navigate } = useUIHistory(initialUri);
  return (
    <UI
      {...rest}
      uri={uri}
      onNavigate={navigate}
      canGoBack={canGoBack}
      onGoBack={goBack}
      canGoForward={canGoForward}
      onGoForward={goForward}
      canGoUp={canGoUp}
      onGoUp={goUp}
    />
  );
}

